import{_ as o,o as i,c as d,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"外掛範例","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/examples.md","filePath":"zh-TW/dev-guide/examples.md","lastUpdated":1785993908000}'),c={name:"zh-TW/dev-guide/examples.md"};function t(a,e,n,s,l,g){return i(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="外掛範例" tabindex="-1">外掛範例 <a class="header-anchor" href="#外掛範例" aria-label="Permalink to &quot;外掛範例&quot;">​</a></h1><p>Lertaro 自帶兩個外掛，都是很有參考價值的真實案例——都在 Lertaro 版本庫的 <code>Plugins/</code> 目錄下。</p><h2 id="coreextensions-——-動作與-shell-右鍵選單" tabindex="-1">CoreExtensions —— 動作與 Shell 右鍵選單 <a class="header-anchor" href="#coreextensions-——-動作與-shell-右鍵選單" aria-label="Permalink to &quot;CoreExtensions —— 動作與 Shell 右鍵選單&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code> 同時實作了三個介面:<code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code>。</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> 回傳十個內建的 <code>ISearchResultAction</code>——開啟、在檔案總管中定位、複製路徑、複製/剪下檔案本身、在其所在位置開啟命令提示字元、touch/mkdir，以及開啟和命令提示字元的提權(以系統管理員身分執行)變體。</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> 回傳一個 <code>IDynamicActionProvider</code>—— <code>ShellMenuActionProvider</code>——正是它讓真正的 Windows 右鍵選單(包括「傳送到」這類串接式子選單)出現在 Lertaro 自己的動作選單裡。如果你想在 Lertaro 裡呈現<em>任何</em>外部、動態建構的選單，而不是一份固定的動作清單，這是值得照抄的模式。</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> 展示了帶巢狀欄位分組和 <code>StringList</code> 欄位型別的設定結構 ——如果你的外掛在設定 → 外掛的設定對話方塊裡需要的不只是一份平坦的布林值清單，值得讀一下這部分。</li><li>有五個提供器實作了 <a href="./sdk/ui-extensions.html#iquickpaneltabprovider"><code>IQuickPanelTabProvider</code></a>，而且它們正好涵蓋了這個介面的兩端。<code>FavoritesTabProvider</code> 和 <code>HistoryTabProvider</code> 原樣交出一份記憶體裡的清單——最精簡參考實作，因為兩者自己都沒有額外的狀態。<code>WindowsRecentTabProvider</code> 則是另一端：它在背景工作上讀目錄、透過 COM 解析 shell 捷徑，<strong>先</strong>截斷再做那件昂貴的事，並給每個項目填上 <code>Metadata.Modified</code>，好讓標籤的「最新在前」真的有意義。</li><li><code>LastDirectoryTabProvider</code> 和 <code>RecentFilesTabProvider</code> 值得讀的理由不太一樣：它們自己壓根沒有資料，而是透過 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 和 <code>RecentFilesService</code> 向宿主要。只要你的外掛想展示的東西 Lertaro 本來就知道，照抄這個模式就對了。</li></ul><h2 id="pinyinalias-——-中文檔名拼音別名" tabindex="-1">PinyinAlias —— 中文檔名拼音別名 <a class="header-anchor" href="#pinyinalias-——-中文檔名拼音別名" aria-label="Permalink to &quot;PinyinAlias —— 中文檔名拼音別名&quot;">​</a></h2><p><code>PinyinAliasProvider</code> 同時實作了 <code>IAliasProvider</code> 和 <code>ITranslationProvider</code>——一個外掛可以自由組合多個相關的 SDK 角色，這是個很好的參考範本:</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> 直接重複使用 <code>PinyinEngine</code> 自己表裡的邊界來宣告這兩個字母表(<code>InputRanges</code>:CJK 區塊;<code>OutputRanges</code>:<code>a</code>-<code>z</code>),不重複寫魔數——宿主用它們支援「大cj」比對「大長今」這類混合了字面漢字和拼音的查詢。</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> 會先掃描是否存在任意中文字元，再決定要不要做實際工作，所以非中文檔名會完全跳過別名產生。</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> 先建構一張按字元劃分的音節表(每個漢字對映到它可能的拼音讀音)，然後產出一個全拼別名和一個首字母別名。對於含多音字(有一種以上有效讀音)的檔名，會為每種常見讀音組合都產生別名——上限 32 種組合，防止極端輸入引發組合爆炸——用 <code>|</code> 連接各個備選項，這樣搜尋引擎會把每一個都當作候選，而不是要求它們同時全部符合。</li><li><strong><code>ITranslationProvider</code></strong> 實作在<em>同一個</em>類別上，純粹是為了給這個外掛自己的介面文字(比如它的顯示名稱)提供翻譯，透過 <code>TranslationService.LoadEmbeddedTranslations</code> 實作——這兩個介面用途上並無關聯，只是碰巧在這個體量很小的單一檔案外掛裡放在了同一個型別上。</li><li>用一個 <code>lock</code> 保護的 <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> 快取避免了每次呼叫 <code>GetTranslations</code> 都重新剖析內嵌的翻譯 JSON——這是任何在 <code>GetTranslations</code> 裡做了非平凡工作的外掛都該採用的標準模式。</li></ul><p>把這兩個外掛對照著看，是理解<a href="./sdk/core-search-actions.html">外掛 SDK 參考</a>裡各個部分如何在實務中配合起來最快的方式。</p>',9)])])}const P=o(c,[["render",t]]);export{u as __pageData,P as default};
